const conversationId = String($json.conversation_id ?? '').trim();
if (!conversationId || conversationId.length > 255 || !/^[A-Za-z0-9_-]+$/.test(conversationId)) throw new Error('conversation_id inválido');
return [{ json: { conversation_id: conversationId } }];

const data = $json;
if (data?.status !== 'done') throw new Error('Somente Atendimentos concluídos podem ser ingeridos');
const transferToolName = $env.ELEVENLABS_TRANSFER_TOOL_NAME;
if (!transferToolName) throw new Error('ELEVENLABS_TRANSFER_TOOL_NAME is required');
const startedAt = new Date(data.metadata.start_time_unix_secs * 1000);
const duration = data.metadata.call_duration_secs;
const contactReason = data.analysis?.data_collection_results?.['Classificação']?.value ?? null;
const transferred = data.transcript.some(turn => turn.tool_calls?.some(call => call.tool_name === transferToolName && call.tool_has_been_called === true));

const firstAgentSpeech = data.transcript.find(turn => turn.role === 'agent' && String(turn.message ?? '').trim());
const tme_seconds = firstAgentSpeech && Number.isFinite(Number(firstAgentSpeech.time_in_call_secs))
  ? Number(firstAgentSpeech.time_in_call_secs)
  : null;
const resultsByCallId = new Map();
let hasToolResults = false;
for (const turn of data.transcript) {
  for (const result of turn.tool_results ?? []) {
    hasToolResults = true;
    if (result?.tool_call_id) resultsByCallId.set(result.tool_call_id, result);
  }
}
const calledTools = [];
for (const turn of data.transcript) {
  for (const call of turn.tool_calls ?? []) {
    if (call?.tool_has_been_called !== true) continue;
    calledTools.push(call);
  }
}
const executions = hasToolResults
  ? [...resultsByCallId.values()].map(result => ({ success: result.is_error !== true }))
  : calledTools.map(() => ({ success: true }));
return [{ json: {
  conversation_id: data.conversation_id,
  agent_id: data.agent_id,
  event_timestamp: data.metadata.start_time_unix_secs + duration,
  status: 'concluido',
  started_at: startedAt.toISOString(),
  completed_at: new Date(startedAt.getTime() + duration * 1000).toISOString(),
  duration_seconds: duration,
  transcript: data.transcript.filter(turn => turn.role === 'agent' || turn.role === 'user').map(({ role, message, time_in_call_secs }) => ({ role, message: message ?? '', time_in_call_secs })),
  audio_reference: null,
  contact_reason: contactReason,
  transferred,
  cost: data.metadata.cost_fiat ?? null,
  tme_seconds,
  tool_executions: { total: executions.length, successful: executions.filter(item => item.success).length }
} }];
